-- 2) DETECTION STEPS (per vendor) ------------------------------------------
INSERT INTO rootcause.detection_steps (vendor_slug, step_type, name, content, expected)
VALUES ('postgresql', 'query', 'Detect SEC-SQL-INJ-001-RC01 (postgresql)',
        '{"sql": "SELECT pid, usename, host(client_addr) AS client_addr, state, query FROM pg_stat_activity WHERE query IS NOT NULL AND state <> ''idle'' AND query ~* ''(xmlparse|xpath\\s*\\(|cast\\s*\\(.*as\\s+(int|numeric))''"}'::jsonb,
        '{"condition": "row_count > 0", "description": "Live/recent statement text matches an injection signature"}'::jsonb);

INSERT INTO rootcause.detection_steps (vendor_slug, step_type, name, content, expected)
VALUES ('sqlserver', 'query', 'Detect SEC-SQL-INJ-001-RC01 (sqlserver)',
        '{"sql": "SELECT r.session_id, s.login_name, t.text AS query FROM sys.dm_exec_requests r JOIN sys.dm_exec_sessions s ON s.session_id = r.session_id CROSS APPLY sys.dm_exec_sql_text(r.sql_handle) t WHERE (t.text LIKE ''%convert(int%'' OR t.text LIKE ''%convert (int%'' OR t.text LIKE ''%cast(0x%'')"}'::jsonb,
        '{"condition": "row_count > 0", "description": "Live/recent statement text matches an injection signature"}'::jsonb);

