-- 4) MONITORING VIEWS (one per root cause) ---------------------------------
CREATE OR REPLACE VIEW monitoring.v_sec_sql_inj_001_rc01 AS
SELECT r.server,
    (j.value ->> 'query') AS query,
    (j.value ->> 'pid') AS pid,
    (j.value ->> 'usename') AS usename,
    (j.value ->> 'client_addr') AS client_addr,
    (j.value ->> 'state') AS state,
    (j.value ->> 'session_id') AS session_id,
    (j.value ->> 'login_name') AS login_name,
    (j.value ->> 'sid') AS sid,
    (j.value ->> 'username') AS username,
    (j.value ->> 'id') AS id,
    (j.value ->> 'user') AS user,
    (j.value ->> 'host') AS host,
    (j.value ->> 'db') AS db,
    r.entry_date
FROM monitoring.general_metric_metadata_results r
  CROSS JOIN LATERAL jsonb_array_elements(r.metric_metadata) j(value)
 WHERE r.metric_name = 'SEC-SQL-INJ-001-RC01';

